    @EventHandler( payloadType=CreateNoteEvent.class )
    public void handle( CreateNoteEvent event) {
	    LOGGER.info("handling CreateNoteEvent - " + event );
	    Note entity = new Note();
            entity.setNoteId( event.getNoteId() );
            entity.setTitle( event.getTitle() );
            entity.setContent( event.getContent() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setUpdatedAt( event.getUpdatedAt() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllNote( entity );
    }

