    /**
     * Method to retrieve the Note via an NotePrimaryKey.
     * @param 	id Long
     * @return 	Note
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Note handle( FindNoteQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getNoteId() );
    }
    
    /**
     * Method to retrieve a collection of all Notes
     *
     * @param	query	FindAllNoteQuery 
     * @return 	List<Note> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Note> handle( FindAllNoteQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindNote,
 * but only if the id matches
 *
 * @param		entity	Note
 */
	protected void emitFindNote( Note entity ) {
		LOGGER.info("handling emitFindNote" );
		
	    queryUpdateEmitter.emit(FindNoteQuery.class,
	                            query -> query.getFilter().getNoteId().equals(entity.getNoteId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllNote
	 * 
	 * @param		entity	Note
	 */
	protected void emitFindAllNote( Note entity ) {
		LOGGER.info("handling emitFindAllNote" );
		
	    queryUpdateEmitter.emit(FindAllNoteQuery.class,
	                            query -> true,
	                            entity);
	}

